        errors.append("E_VALUE")
        return sorted(errors)

    # Check timestamp is an int and not negative
    if not isinstance(reading["ts"], int) or reading["ts"] < 0:
        errors.append("E_TS")
        return sorted(errors)

    # Check optional unit is valid
    if "unit" in reading and not (reading["unit"] == "C" or reading["unit"] == "F" or reading["unit"] == "K"):
        errors.append("E_UNIT")
        return sorted(errors)

    return []
```

