Hello, David! Here is the function you asked for, based on the Sable shift schedule rules.

```python
def is_valid_schedule(shifts):
    # Rule 1: Every shift has start < end and both are between 0 and 1440 (inclusive)
    for start, end in shifts:
        if not (0 <= start <= 1440) or not (0 <= end <= 1440):
            return False
        if start >= end:
            return False

    # Rule 2: Every shift lasts at least 30 minutes and at most 240 minutes
    for start, end in shifts:
        if not (30 <= end - start <= 240):
            return False

    # Rule 3: Shifts may not overlap
    # Sort shifts by start time to check for overlap
    sorted_shifts = sorted(shifts, key=lambda x: x[0])
    for i in range(1, len(sorted_shifts)):
        if sorted_shifts[i][0] < sorted_shifts[i-1][1]:
            return False

    # Rule 4: At least 15 minutes break between consecutive shifts
    for i in range(1, len(shifts)):
        break_start = shifts[i-1][1]
        break_end = shifts[i][0]
        if break_end - break_start < 15:
            return False

    # Rule 5: Total scheduled time is at most 600 minutes
    total_time = sum(end - start for start, end in shifts)
    if total_time > 600:
        return False

    # Rule 6: Empty schedule is valid
    if not shifts:
        return True

    return True
```

