                    num += char
                else:
                    if num:
                        parts.append(num)
                        num = ""
                    if part == "h" or part == "m" or part == "s":
                        break
            if num:
                parts.append(num)

    # At least one part is required
    if not parts:
        return None

    # Convert parts to integers
    hours = 0
    minutes = 0
    seconds = 0
    for part in parts:
        if part == "h":
            hours = int(part)
        elif part == "m":
            minutes = int(part)
        elif part == "s":
            seconds = int(part)

    # Apply fixes from bug reports
    # 1. Allow any number of digits and any value (fix for 60+)
    # No change needed

