    # Apply all FLAT discounts in order
    for code in codes:
        if code.startswith("FLAT"):
            try:
                amount = int(code[4:])
                price -= amount
            except ValueError:
                continue  # Ignore invalid codes

    # Ensure the price is not below 0
    if price < 0:
        price = 0

    return price
```

