        return False

    # Check if each part has exactly 4 characters
    for part in parts:
        if len(part) != 4:
            return False

    # Check if all characters are in theallowed alphabet
    allowed_alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
    for part in parts:
        for char in part:
            if char not in allowed_alphabet:
                return False

    # Calculate the check character
    # Take the first 11 characters (excluding the last one), sum their values, mod 32
    first_11_chars = code[:11]  # first 11 characters, excluding the last one
    total = 0
    for char in first_11_chars:
        total += ord(char) - ord('2')  # subtract the ASCII value of '2' to get the position in thealphabet

    check_char_value = total % 32
    check_char = allowed_alphabet[check_char_value]

    # Check if the last character matches the check character
    if code[-1] != check_char:
        return False

    return True
