def round_price(cents):
    # Handle the case where cents is zero
    if cents == 0:
        return 0

    # Calculate the nearest multiple of 10 cents, rounding away from zero
    # For example, 25 becomes 30, 35 becomes 40, -25 becomes -30, -14 becomes -10
    # We can do this by dividing by 10, rounding up if the remainder is 5 or more
    # Then multiply by 10
    if cents > 0:
        # For positive numbers, round away from zero
        # If cents % 10 >= 5, round up, else round down
        if cents % 10 >= 5:
            return (cents // 10 + 1) * 10
        else:
            return (cents // 10) * 10
    else:
        # For negative numbers, round away from zero
        # If cents % 10 <= -5, round down, else round up
        if cents % 10 <= -5:
            return (cents // 10 - 1) * 10
        else:
            return (cents // 10) * 10
```

